// JAPANESE — the fifth catalog. Machine-assisted, written to the same contract as de.ts.
//
// PARTIAL BY DESIGN. Every key absent here resolves to the English source string at runtime
// (`rawMessage` falls through), so a missing translation is a Japanese screen with an English
// sentence on it — never a blank and never a key.
//
// ⚠️ WHAT IS NOT TRANSLATED HERE, AND WHY IT MUST STAY THAT WAY: frequencies and every number
// that is one, signal reports, callsigns, grid squares, band and mode names, Q-codes, RST,
// POTA/SOTA references, ADIF field names, CW macro tokens, award names and product names.
// Numbers never carry a thousands separator — a digit-comma-digit sequence fails
// `placeholders.test.ts` — and stay half-width. Japanese has no grammatical plural (CLDR `ja`
// selects `other` for every count), so entries that are plural objects in en.ts are plain
// strings here, translated from the `other` form — NEVER both forms concatenated, which is the
// bug the fr/es catalogs shipped with.
//
// REGISTER: labels are terse noun-style (保存, not 保存します); hints and errors are です・ます体;
// the subject is omitted rather than あなた; established JA ham vocabulary over dictionary
// Japanese (ゼロイン, コンファーム, Eスポ, リニアアンプ, S&P（呼び回り）).
//
// Placeholders may MOVE (Japanese word order differs — that is why they exist); they may never
// be renamed, dropped or added.

