  "assist.sources.offSince": "アシストソースは{{since}}からオフです: AI CWデコーダー、DXクラスター／RBN、PSK Reporterニーズ。",
  "assist.sources.on": "AI CWデコーダー、DXクラスター／RBN、PSK Reporterニーズがコールサインの特定に使われています。",
  "assist.sources.onSince": "{{since}}から、AI CWデコーダー、DXクラスター／RBN、PSK Reporterニーズがコールサインの特定に使われています。",
  "assist.toggle.declare": "UNASSISTEDでの参加を宣言",
  "assist.toggle.end": "UNASSISTEDでの参加を終了",
  "assist.why.summary": "コンテストのカテゴリーにどう関わるか",
  "assist.why.cqww": "<b>CQ WW</b>のルールVIII.2は “a CW decoder, DX cluster, DX spotting Web sites … local or remote call sign and frequency decoding technology (e.g., CW Skimmer or Reverse Beacon Network)” をQSO探索のアシスタンスに数えています。これらのいずれかを使うと、エントリーはSingle Operator（V.A.1）ではなく<b>Single Operator Assisted</b>（V.A.2）になります。",
  "assist.why.arrl": "<b>ARRL</b>のコンテストではこれをspotting assistanceと呼び、“PSKReporter, Telnet, DX spotting websites or bulletin board systems, automated multi-channel decoders” を挙げています。Single Operatorは使用できません（HCAT.1.1: “Use of spotting assistance is not permitted.”）。<b>Single Operator Unlimited</b>は使用できます（HCAT.2.1）。ARRLの用語集はmulti-channel decoderを “displays multiple decoded signals at the same time” というソフトウェアと定義しています。Nexusは信号を1つずつデコードするため、この定義はNexusのCWデコーダーには当てはまりません。クラスター、RBN、PSK Reporterのフィードには当てはまります。",
  "assist.why.ownDecodes": "<b>自局の無線機のデコード</b>はどちらのルールでもアシスタンスに当たらないため、UNASSISTEDモード中も未交信ボードへの供給は続きます。PSK Reporterへの自局からのアップロードも動き続けます。ARRLが “Generating spotting information for use by other stations is not considered to be spotting assistance.” としているためです。",
  "assist.why.notCovered": "<b>このスイッチが対象にしないもの:</b> POTAとSOTAのアクティベータースポットは引き続き届きます。どちらのルールもこれらのフィードを名指ししてはいませんが、アシスタンスの定義は十分広く、含まれ得ます。これらを数えるコンテストに出る場合は、POTA/SOTA機能を手動でオフにしてください。",
  "assist.why.checkRules": "ルールはコンテストごとに異なり、年によっても変わります。<b>参加するコンテストのルールを必ず確認してください</b>。このノートはCQ WWとARRLが現在公表している内容を伝えるものであり、カテゴリーの裁定ではありません。",
  "assist.keep": "自分の設定が書き換えられることはありません。UNASSISTEDモードを終了すると、デコーダーとフィードは元の状態にそのまま戻ります。",
