  "roam.title": "協調QSY・Roam",
  "roam.subtitle": "QRMやその場限りのワッチを避けて相手局と一緒に移動",
  "roam.disclaimer": "<b>秘匿ではありません — 移動は平文でアナウンスされます。</b>協調QSYは、自局ともう一つの局が一緒に新しいチャンネルへ移る機能で、移動の内容は平文で送信されます（FCC Part 97は暗号化や意味の秘匿を禁じており、コールサインは10分ごとに送出されます）。元の周波数に留まっている<em>その場限りの</em>ワッチは振り切れますが、広帯域受信機を持つ相手からは<em>隠れられません</em> — 追従できてしまいます。QRM対策とささやかな目立ちにくさのために使い、秘匿目的では決して使わないでください。",
