  "settings.pounce.legend": "パウンス — ニューワンアラート",
  "settings.pounce.note": "必要な局がクラスターやRBNに現れたその瞬間に割り込みます — スポットボードの更新を待ちません。Nexusを見ていなくても大きなトーンが鳴り、バナーのワンクリックで交信に移れます。オンにするまでは無効です。「レア」の基準は自局の実績で決まります: 最初の100エンティティを追っている段階ではほとんどのDXスポットがニューになり、これは鳴りやみません。ニューが本当にイベントになるほどログが進んでから、まず<em>ニューDXCCエンティティのみ</em>で始めるのがおすすめです。各局のアラートはバンド・モードごとに1回です。",
