  "sat.rail.uplink.confirmMapping.title": "{{rig}}で{{mapping}}（自分で選んだマッピング）を確認します。この無線機で確認するまで送信VFOには何も書き込まれません。誤ったマッピングは自局のダウンリンク上に送信してしまいます。",
  "sat.rail.vfoMap.aria": "衛星VFOマッピング",
