  "settings.routing.intro": "<b>バンドとモードでルーティング</b> — 上のバンドカバレッジはバンド全体を1台に割り当てます。2台がバンドを共有し、モードで振り分けたい場合はここにルールを追加します: 2 m のFT8はデジタル機へ、2 m のFMとAPRSはFM機へ。ルールは上から順に判定され、最初に一致したものが適用されます。どのルールにも一致しない場合はバンドカバレッジ、次にデフォルトの無線機になります。",
