  "settings.audio.legend": "オーディオ",
  "settings.audio.multiRadio.note": "🎚 以下のオーディオデバイスは<b>{{radio}}</b>用です。無線機ごとに専用の入出力があります。別の無線機のオーディオを設定するには、上の無線機一覧でその無線機の「編集」をクリックしてください。ライブのRXオーディオとウォーターフォールは、アクティブな無線機に追従します。",
  "settings.audio.multiRadio.selectedRadio": "選択中の無線機",
  "settings.audio.device.systemDefault": "システムデフォルト",
  "settings.audio.input.label": "入力デバイス (RX)",
  "settings.audio.input.hint": "受信オーディオが入ってくるサウンドカードです。",
  "settings.audio.refresh.action": "更新",
  "settings.audio.refresh.title": "オーディオデバイスを再スキャン",
  "settings.audio.output.label": "出力デバイス (TX)",
  "settings.audio.output.hint": "無線機へ送るサウンドカードです（送信）。",
  "settings.audio.spectrum.label": "入力スペクトラム（ライブ）",
  "settings.audio.spectrum.idle": "フラット — 選択した入力にオーディオがありません。上のデバイスを確認してください（無線機の電源、コーデックの選択）。",
  "settings.audio.spectrum.hint": "選択した入力が今聞いている音のライブ表示です。バンドノイズが動くノイズフロアとして見えるはずです。設定画面を離れる前に、正しいデバイスかどうか確認できます。",
  "settings.audio.txPower.label": "送信出力",
  "settings.audio.txPower.aria": "送信ドライブレベル",
  "settings.audio.txPower.hint": "無線機へのオーディオ<b>ドライブ</b>量 — コックピットの<b>Pwr</b>スライダーと同一の設定です（常に連動します）。無線機のALCがちょうどゼロになるまで下げてください。これは無線機のRF出力（ワット）<em>ではありません</em>。RF出力は無線機側で設定してください。",
  "settings.audio.rxLevel.label": "RXレベル",
  "settings.audio.rxLevel.meter": "RXオーディオレベル",
  "settings.audio.rxLevel.hint": "WSJT-Xと同様のdBスケールです。30 dB前後を目安にしてください。およそ15–60 dBの範囲なら問題なくデコードできます。赤は過大入力です（RXゲインまたは無線機側のオーディオを下げてください）。",
  "settings.audio.rxGain.label": "RXゲイン",
  "settings.audio.rxGain.aria": "RXキャプチャゲイン",
  "settings.audio.rxGain.hint": "入力の小さいインターフェースを、RXレベルが30 dB前後になるまで増幅します。メーターはスライダーを離すと反応します。メーターが低い（約15 dB未満）場合を除き×1.0のままにしてください。FT8は小さい信号でもデコードできるため、大きく上げる必要はほとんどありません。",
  "settings.headphoneMonitor.legend": "このコンピューターでの受信音",
  "settings.headphoneMonitor.enable.label": "受信音をここで再生",
  "settings.headphoneMonitor.enable.aria": "受信音をこのコンピューターで再生",
  "settings.headphoneMonitor.enable.hint": "受信オーディオ — デコーダーが聞いているそのままの音 — をこのコンピューターのデバイスから再生します。レベルやRFIの診断に、あるいは単にバンドを聞くために使えます。送信モニターではありません。自分の声が返ってくることは決してありません。デフォルトはオフです。立ち会いセッションまでオンエアでの動作は未検証です。",
  "settings.headphoneMonitor.device.label": "ヘッドホンまたはスピーカー",
  "settings.headphoneMonitor.device.hint": "自分のヘッドホンまたはスピーカーを指定します。無線機のTX出力デバイスには絶対にしないでください。",
  "settings.headphoneMonitor.level.label": "再生音量",
  "settings.headphoneMonitor.level.aria": "受信音の再生音量",
  "settings.headphoneMonitor.level.hint": "ヘッドホンで聞く音量です（TXには影響しません）。",
  "settings.satelliteDoppler.legend": "衛星ドップラー",
  "settings.satelliteDoppler.note": "パスの両側を補正します: 受信するダウンリンクと送信するアップリンクです。Nexusが同調を行うのは、自動追尾がパスを追っていて、衛星セクションでトランスポンダーを選択している間だけです。ダウンリンクはここでの設定は不要です。アップリンクは無線機ごとに、実際のパス上で一度確認します。",
  "settings.satelliteDoppler.enable.label": "ドップラー補正",
  "settings.satelliteDoppler.enable.aria": "衛星ドップラー補正を有効化",
  "settings.satelliteDoppler.enable.hint": "パスの間、無線機を追従同調させて交信中の相手局に留まれるようにします。オン: パスをアームしトランスポンダーを保持すると、ただちにダウンリンクが衛星に追従します。オフにすると両側とも停止します。",
  "settings.satelliteDoppler.vfoMap.label": "VFOマッピング",
  "settings.satelliteDoppler.vfoMap.aria": "衛星VFOマッピング",
  "settings.satelliteDoppler.vfoMap.otherRadio": "アップリンクのマッピングは、運用中の無線機ごとに確認します。この無線機で確認するには、パス中にパスレールで確認するか、先にこの無線機をアクティブにしてください。",
  "settings.satelliteDoppler.vfoMap.hint": "どのVFOがアップリンクを担うかの設定です。無線機の配線に合わせてください。<b>誤ったマッピングは自局のダウンリンク周波数で送信します</b> — 衛星の出力帯域の中、つまりその衛星を運用中の全員の上にかぶせることになります。選択すると即座に適用され、運用中の無線機について確認済みになります。2台目の無線機はパスレールで別途確認します。「Uplink only」以外のマッピングでは、ダウンリンクの補正は維持されます。",
  "settings.satelliteDoppler.minShift.label": "最小シフト (Hz)",
  "settings.satelliteDoppler.minShift.aria": "再同調する最小ドップラーシフト (Hz)",
  "settings.satelliteDoppler.minShift.hint": "これより小さい補正は送りません。20 HzはSSBでは聞き取れない差で、CATリンクを静かに保てます。0にするとすべての更新を送ります。",
  "settings.satelliteDoppler.interval.label": "更新間隔 (ms)",
  "settings.satelliteDoppler.interval.aria": "ドップラー更新間隔（ミリ秒）",
  "settings.satelliteDoppler.interval.hint": "補正と補正の最短間隔です。低軌道のパスには1000 msで十分です。これより短いと自分の同調操作と競合し、シリアルのCATリンクが飽和します。",
  "settings.satelliteDoppler.passSounds.label": "パス通知音",
  "settings.satelliteDoppler.passSounds.aria": "パスの開始と終了の通知音",
  "settings.satelliteDoppler.passSounds.hint": "アームしたパスの開始時に上昇音、終了時に下降音を、ポップアップと併せて鳴らします。ローテーターに手を置いたままAOSが分かります。デフォルトはオンです。オフにしても消えるのは音だけで、ポップアップは表示されます。",
  "settings.orbitalElements.legend": "軌道要素",
  "settings.orbitalElements.update.action": "今すぐ更新",
  "settings.orbitalElements.update.busy": "更新中…",
