  "settings.orbitalElements.import.title": "ダウンロード済みの軌道要素ファイル（Celestrak TLE、AMSATのケプラー要素、新規打ち上げのSupGPセット）をインポートします — オフラインシャックのための手段です。インポートした要素は更新後も保持され、衛星ごとに最新のエポックが優先されます。",
  "settings.orbitalElements.import.ok": "軌道要素をインポートしました — {{imported}}件インポート、合計{{total}}件",
