  "settings.amplifier.model.label": "アンプ",
  "settings.amplifier.model.none": "なし",
  "settings.amplifier.model.hint": "読み取り値を見るには、コネクトにアンプパネルを配置してください。ここの設定が無線機の送信動作を変えることはありません。",
  "settings.amplifier.follow.label": "無線機のバンドに追従",
  "settings.amplifier.follow.hint": "操作なしでアンプを現在のバンドへ切り替えます。デフォルトはオフです — これはアンプ関連で唯一、自動で動作する設定です。送信中にアンプを動かすことは決してなく、1バンドずつステップし、そのたびにアンプが実際にどのバンドにいるかを確認してから次へ進みます（着いたはずと仮定しません）。⚠️ 多くのSPEの設置例のように、アンプが専用のバンドデータケーブルで既に無線機に追従している場合は、オフのままにしてください。ハードウェアが同じ仕事をしており、1つのバンドを2系統で操るのはどちらか一方だけより悪い結果になります。",
  "settings.amplifier.port.label": "アンプのポート",
