  "setup.log.title": "これまでのログを取り込む",
  "setup.log.sub": "Nexusは交信履歴を知っているほど役に立ちます。ADIFログをインポートすると、<b>交信済み</b>フラグ、<b>Needed</b>ボード（未交信のDXCC/州/グリッド）、<b>アワード</b>の進捗が使えるようになります。インポートしないと、アプリはすべての局を初交信として扱います。この手順は任意で、後からログブックでいつでもインポートできますが、初日からアプリを役立てる一番の近道です。",
