  "setup.log.sources": "WSJT-X、N1MM、Log4OM、HRD、QRZ、LoTW、ClubLogなど、標準のADIF (.adi/.adif) エクスポートに対応。データがコンピューターの外に出ることはなく、重複は検出してスキップします。",
  "setup.finish.title": "すべてが使えます",
  "setup.finish.sub": "すべてのモードとセクションが最初からオンです — FT8/FT4、Phone、CW、RTTY、SSTV、APRS、衛星、マップ、その他すべて。Nexusは6本のソフトの代わりになる1本のプログラムで、アンロックするものはありません。身軽にしたければ、後で設定からセクションを減らせます。",
  "setup.finish.license.title": "免許の種類は？",
