  "settings.aprs.ssid.satellite": "衛星／特殊",
  "settings.aprs.ssid.handheld": "ハンディ機",
  "settings.aprs.ssid.boat": "船舶／マリタイムモービル",
  "settings.aprs.ssid.mobile": "モービル（車）",
  "settings.aprs.ssid.igate": "iGate／インターネット",
  "settings.aprs.ssid.balloon": "気球／航空機",
  "settings.aprs.ssid.tracker": "トラッカー",
  "settings.aprs.ssid.weather": "気象局",
  "settings.aprs.ssid.truck": "トラック／貨物",
  "settings.aprs.is.title": "APRS-IS（インターネットフィード）",
  "settings.aprs.is.enabled.label": "APRS-ISフィード",
  "settings.aprs.is.enabled.hint": "インターネット経由で報告された局を、自局のアンテナで聞こえた局と並べてプロットします — どちら由来かは常にタグで区別できます。APRSデコーダーのアーム状態に関係なく動作し、無線機を使わず送信も一切しません。インターネットの局は表示されるのに受信が無音なら、障害はRF側にあります。",
  "settings.aprs.is.host.label": "サーバー",
  "settings.aprs.is.host.hint": "地域のTier 2ローテートが最適です — noam / soam / euro / asia / aunz の各.aprs2.net。<code>{{host}}</code>はどこからでも使えます。",
  "settings.aprs.is.port.label": "ポート",
  "settings.aprs.is.port.hint": "14580はクライアントとiGateが使うべきフィルター付きポートです。フルフィードのポートでは全世界のデータが流れ込んできます。",
  "settings.aprs.is.radius.label": "半径（km）",
  "settings.aprs.is.radius.hint": "グリッドスクエアの周囲どこまで購読するかです。APRSはローカルなモードで、150 kmは2 m + デジピーターの到達範囲として十分広めです。0 = 距離制限なし（混み合います）。",
  "settings.aprs.is.watchCalls.label": "ウォッチするコール",
  "settings.aprs.is.watchCalls.hint": "カンマ区切りで指定します。半径をどれだけ外れていても、地球上のどこからでも届きます — 遠征中のクラブのトラッカーや、山頂を目指す友人などに。",
  "settings.aprs.is.weather.label": "気象局",
  "settings.aprs.is.weather.hint": "フィードに気象レポートを含めます。",
  "settings.aprs.is.objects.label": "オブジェクトとアイテム",
  "settings.aprs.is.objects.hint": "他局がマップ上に置いたレピータ、NWS警報、イベントマーカーです。",
  "settings.aprs.is.messages.label": "メッセージ",
  "settings.aprs.is.messages.hint": "フィードのAPRSテキストメッセージを表示します。表示のみで、インターネットメッセージへの返信機能はありません。",
  "settings.aprs.stationTtl.label": "局の保持時間（分）",
  "settings.aprs.stationTtl.hint": "最後のパケットのあと、局をマップに残しておく時間です。この3分の1を過ぎるとフェードが始まります。デフォルトは1時間。固定局のビーコンは10〜30分間隔のことが多く、短くしすぎると遅い局が自分のビーコンの合間に消えてしまいます。0はすべての局を永久に保持します（フェードも削除もなし — 2000局の上限は引き続き適用されます）。",
  "settings.aprs.is.uplink.label": "受信専用iGate",
  "settings.aprs.is.uplink.hint.call": "<b>自局のアンテナで受信した</b>パケットをAPRS-ISに提供し、周辺の局が自局経由で世界地図に載るようにします。<b>{{call}}</b>の名義で公開されるため、フィードを見るのとは別の選択であり、送るものを得るにはAPRSデコーダーが動いている必要があります。逆方向の送出はNexusでは行いません。インターネットの内容を電波に戻すことは無人送信を意味するためです。",
  "settings.aprs.is.uplink.hint.noCall": "<b>自局のアンテナで受信した</b>パケットをAPRS-ISに提供し、周辺の局が自局経由で世界地図に載るようにします。自局のコールサインの名義で公開されるため、フィードを見るのとは別の選択であり、送るものを得るにはAPRSデコーダーが動いている必要があります。逆方向の送出はNexusでは行いません。インターネットの内容を電波に戻すことは無人送信を意味するためです。",
  "settings.workingFrequencies.legend": "運用周波数",
  "settings.workingFrequencies.note": "バンド／モードを選択したときに使われるダイヤル周波数です。これはWSJT-X標準の運用周波数テーブルへの<b>オーバーライド</b>で、リストを空にすればすべて標準値が使われます。オーバーライドは該当バンド + モードの標準行を置き換えます（例：FT8を代替サブバンドへ移す）。",
  "settings.workingFrequencies.stock.label": "標準テーブル（読み取り専用）",
  "settings.workingFrequencies.stock.band": "バンド",
  "settings.workingFrequencies.stock.mode": "モード",
