  "settings.integrations.saveWav.hint": "WAVはrecordings/periodsに保存されます（12 kHzモノラル、各約360 KB）。「すべての周期を保存」は連続監視で1日あたり約2 GBを書き込みます — 常時オンではなく、デコーダーのデバッグ用に使ってください。",
  "settings.integrations.spotSources.title": "スポットソース",
