  "settings.integrations.clusterNodes.remove.title": "このクラスターノードを削除",
  "settings.integrations.clusterNodes.remove.aria": "{{host}}を削除",
  "settings.integrations.clusterNodes.remove.ariaBlank": "ノードを削除",
  "settings.integrations.clusterNodes.add.option": "+ 既知のノードを追加…",
