  "settings.integrations.clusterNodes.addCustom.action": "+ カスタム",
  "settings.integrations.clusterNodes.hint": "リストのすべてのノードに接続し、人によるSSB/フォーンのスポットを統合します — ノードが多いほどフォーンのカバレッジが広がります（RBNのCW + デジタルは自動接続。RBNのエンドポイントをここに書いても無視されます）。追加したノードは次回の保存で接続され、削除は再起動後に反映されます。",
  "settings.integrations.propagation.title": "伝搬",
  "settings.integrations.openingWatch.label": "近隣地域のオープン監視",
  "settings.integrations.openingWatch.hint": "自局QTH付近のVHF/10 mのアクティビティを（自局の交信だけでなく）監視し、誰とも交信する前に「周辺でオープン中」と知らせます。再起動後に有効になります。",
  "settings.integrations.propEngine.label": "予測エンジン",
  "settings.integrations.propEngine.heuristic": "モデル計算（高速ヒューリスティック）",
  "settings.integrations.propEngine.p533": "ITU-R P.533（完全な物理計算）",
  "settings.integrations.propEngine.hint": "局ごとのパス見通しと24時間のバンド×時刻グリッドを駆動します。P.533は本物の回線信頼度計算法です（ITUリファレンスと照合検証済み。1予測あたり約0.1 s、自局の出力を使用）。ライブのスポットは常にどのモデルよりも優先されます。",
  "settings.antennaGain.title": "アンテナ利得（詳細）",
  "settings.antennaGain.label": "アンテナ利得（dBi） — TX / RX",
  "settings.antennaGain.tx.aria": "TXアンテナ利得（dBi）",
  "settings.antennaGain.rx.aria": "RXアンテナ利得（dBi）",
  "settings.antennaGain.hint": "P.533のリンクバジェット計算のみで使われます。0 = 単純なワイヤー／バーチカル（等方性）、3エレ八木 ≈ 6–8。正直なv1実装で、単純なdBシフトのみ — パターンや打ち上げ角のモデル化はなく、高速ヒューリスティックはこの値を無視します。",
  "settings.dxkeeper.note": "記録した各QSOをTCP Network Service経由で<b>DXKeeper</b>に送ります。先にDXKeeper側の<em>Configuration ▸ Defaults ▸ Network Service</em>で有効にしてください。",
  "settings.dxkeeper.host.label": "DXKeeperホスト",
  "settings.dxkeeper.host.placeholder": "{{example}}（空欄 = オフ）",
  "settings.dxkeeper.host.hint": "通常は127.0.0.1（同じPC）です。空欄で無効になります。",
  "settings.dxkeeper.basePort.hint": "DXKeeperのNetwork Serviceパネルにある<em>Base Port</em>です（デフォルト52000）。DXKeeper自体は<b>{{port}}</b>で待ち受けます — +1はNexusが自動で行います。",
  "settings.dxkeeper.uploads.label": "アップロードをDXKeeperに任せる",
  "settings.dxkeeper.uploads.hint": "デフォルトはオフです。NexusがすでにLoTW / eQSL / ClubLog / QRZへアップロードしているため、オンにするとすべてのQSOが二重にアップロードされます。なおDXKeeperは、自身のQSL Configurationタブで<em>Auto upload</em>にチェックが入っているとClub LogとQRZについてこの設定を無視します — そちらのチェックを外してください。",
  "settings.n3fjp.legend": "N3FJP連携（クラブのマスターログ）",
  "settings.n3fjp.note": "フィールドデーの各交信は、記録した瞬間にクラブの<b>N3FJP Field Day Contest Log</b>に反映され、クラブ全体のスコアがリアルタイムで更新されます。マスターのコンピューターでN3FJPを起動し、そのIPとポート（デフォルト1100）をNexusに指定してください。",
  "settings.n3fjp.host.label": "N3FJPホスト",
  "settings.n3fjp.host.placeholder": "{{example}}（空欄 = オフ）",
  "settings.n3fjp.host.hint": "マスターログのコンピューターのIPまたはホスト名です。空欄で無効になります。",
  "settings.n3fjp.port.label": "N3FJPポート",
  "settings.n3fjp.port.hint": "N3FJPのAPI TCPポートです（デフォルト1100）。",
  "settings.n3fjp.useEnter.label": "フィールドデーの得点計上にENTERを使う",
  "settings.n3fjp.useEnter.hint": "各フィールドデー交信をN3FJPの<b>ENTER</b>シーケンスで記録します。コンテストの得点が計上される正しい経路です。オフにすると単純な<code>ADDDIRECT</code>挿入にフォールバックします（得点計上されない場合があります）。デフォルトはオンです。",
  "settings.n3fjp.reportBand.label": "自局のバンドをN3FJPに報告",
  "settings.n3fjp.reportBand.hint": "運用中のバンドをN3FJPに伝えます（CAT不要）。クラブのNetwork Status Displayのバンドボードにこのポジションが表示されます。デフォルトはオフです。",
  "settings.n3fjp.forwardAll.label": "すべてのQSOを転送",
  "settings.n3fjp.forwardAll.hint": "フィールドデーに限らず、記録した<b>すべての</b>QSOを上記ホストのN3FJP ACLogにも送ります — 普段の一般ロギング向けです。N3FJP側で重複排除されるため、フィールドデー転送と併用しても安全です。",
  "settings.n3fjp.test.label": "接続テスト",
