  "settings.confirmations.lotw.sync.hint": "これはコンファームを<b>ダウンロード</b>するだけです。交信をLoTW<em>へ</em>送るには、ログブックの<b>LoTWへアップロード (N)</b>を使ってください。新しいコンファームをログに取り込み、LoTWが受理済みのアップロードに印を付けます（「未アップロード」ではなく「相手局待ち」と表示されるようになります）。初回は全履歴が対象のため時間がかかることがあり、以降は差分のみです。",
  "settings.confirmations.lotw.stationLocation.label": "LoTWステーションロケーション",
