  "aprs.radioNote.label": "{{name}}で受信中",
  "aprs.radioNote.detail": "このバンドに対応する無線機が{{count}}台あるため、APRSはどれを使うか選ぶ必要があります。アクティブな無線機（現在は{{name}}）に追従します — パケット音声を接続した無線機と違う場合、それが何もデコードされない原因です。どのバンドをどの無線機に割り当てるかはルーティングルールで決まります: 設定 → 無線機。",
  "aprs.health.level.silence": "直近0.1秒の入力: デジタル無音（完全にゼロ）",
  "aprs.health.level.peak": "直近0.1秒の入力ピーク: {{db}} dBFS",
  "aprs.health.dbfs.silence": "無音",
  "aprs.health.norf.label": "2m無線機なし",
  "aprs.health.norf.detail": "この無線機は{{freq}} MHzに対応していないため、RFのAPRSを受信できません。RF APRSにはVHF無線機が必要です。インターネットフィードは無線機がなくても動作します — オンにすると、他局が報告したAPRSトラフィックを確認できます。",
  "aprs.health.off.label": "モニター オフ",
  "aprs.health.off.detail": "APRSデコーダーは動作していません。モニターを起動するとRX音声をデコードします。",
  "aprs.health.wrongFreq.label": "周波数違い",
  "aprs.health.wrongMode.label": "モード違い",
  "aprs.health.wrongMode.detail": "無線機は{{want}}に合っていますが、モードが{{mode}}です — APRSにはFMが必要です。FMのパケット音声をSSBで復調すると崩れるため、信号がどれだけ強くてもデコードできません。APRSチャンネルにチューンすると受信が始まります。",
  "aprs.health.wrongFreqMode.detail": "無線機は{{dial}} {{mode}}になっています — APRSには{{want}} FMが必要です。このチャンネルの信号は、音声レベルにかかわらずAPRSパケットとしてデコードできません。APRSチャンネルにチューンすると受信が始まります。",
  "aprs.health.wrongFreq.detail": "無線機は{{dial}}になっています — APRSには{{want}}が必要です。このチャンネルの信号は、音声レベルにかかわらずAPRSパケットとしてデコードできません。APRSチャンネルにチューンすると受信が始まります。",
  "aprs.health.noCapture.label": "入力なし",
  "aprs.health.noCapture.detail": "起動していますが、音声サンプルがまったく届いていません — キャプチャデバイスが何も出力していません。設定 ▸ 無線機 ▸ オーディオの入力デバイス（RX）が無線機になっているか確認してください（マイクや外れたデバイスではなく）。スピーカーから聞こえる音は、アプリが何をキャプチャしているかとは別物です。",
  "aprs.health.decoding.label": "{{count}}件デコード",
  "aprs.health.decoding.detail": "起動後に{{count}}パケットをデコードしました。{{level}}。",
  "aprs.health.decoding.detail.aged": "起動後に{{count}}パケットをデコード、最後は{{age}}前です。{{level}}。",
  "aprs.health.unreadable.label": "{{count}}件CRC不合格",
  "aprs.health.unreadable.detail": "起動後に{{count}}回のバーストを受信、最後は{{age}}前です — いずれもチェックサムを通過していません。ある程度は正常です: バーストの途中でスケルチが開くとパケットの先頭が失われ、途中からのパケットは決して通過できません。まったくデコードされない場合のみ異常です — その場合は無線機が{{channel}}のFMになっているか確認してください。{{advice}}直近のバーストのピークは{{burst}}、{{level}}。",
  "aprs.health.advice.clipping": "バーストがクリップしています（ピーク{{peak}}、{{samples}}サンプルが振り切れ）— 無線機のUSB AF出力レベル、またはそのデバイスのWindows入力レベルを下げてください。パケットはかなりのクリップにも耐えるため、失うのはデコードよりヘッドルームですが、振り切らせておく理由はありません。",
  "aprs.health.advice.quiet": "バーストのピークは{{peak}}で、健全な{{min}}〜{{max}}の範囲よりかなり低めです — 無線機のUSB AF出力レベル（IC-9700: SET > Connectors > USB AF Output Level）またはそのデバイスのWindows入力レベルを上げてください。ノイズに対する余裕は増えますが、それ自体がチェックサム失敗の原因ではありません。",
  "aprs.health.silent.label": "無音",
  "aprs.health.silent.detail": "入力は生きていて音声は届いていますが、無音です — 通常はパケット間でスケルチが閉じているだけで、待機中のFMチャンネルはこう見えます。ルーティングを確認するにはスケルチを開いてください: ホワイトノイズがレベルとしてここに現れるはずです。スケルチを開いても無音のままなら、入力デバイスの選択が間違っています。{{level}}。",
  "aprs.health.listening.label": "待ち受け中",
  "aprs.health.listening.detail": "音声はデコーダーに届いていますが、最近パケットは受信していません — 静かなチャンネルです。{{level}}。スケルチを開くとホワイトノイズが{{hiss}}前後になり、パケットのバーストは{{min}}〜{{max}}でピークになるはずです。",
