  "psk.send.noCallsign": "送信する前に設定で自局のコールサインを設定してください",
  "psk.send.noTheirCall": "先に相手局のコールを入力してください（{CALL} 欄）",
  "psk.send.txLocked": "TX ロック中 — この周波数は免許の範囲外です",
  "psk.send.failed": "PSK の送信に失敗しました",
  "psk.latch.failed": "連続送信が拒否されました",
  "psk.type.failed": "PSK の入力送信が拒否されました",
  "psk.drive.text": "無線機の ALC はほぼゼロに保ってください — 過大入力の PSK31 信号はスプラッタ（IMD）を出します。ALC メーターがほとんど振れなくなるまで TX オーディオを下げてください。",
  "psk.drive.title": "PSK31 は振幅整形されたモードです。無線機の ALC が圧縮をかけると信号が隣にスプラッタします（IMD）。Nexus はデフォルトで控えめなドライブでキーイングします — 無線機の ALC メーターがほとんど振れないように TX オーディオ / 出力を設定してください。",
  "sstv.refuse.heic": "iPhone の HEIC 写真はここでは読み込めません — Nexus に HEVC デコーダーがないためです。iPhone 側で: 設定 → カメラ → フォーマット → 互換性優先（以降の写真は JPEG になります）、または 設定 → 写真 → MacまたはPCに転送 → 自動（転送時に変換）。そのうえでこの写真をもう一度送ってください。",
  "sstv.refuse.avif": "これは AVIF ファイルです。SSTV で送れるのは JPEG・PNG・WebP・BMP・GIF です — いずれかの形式で書き出すか保存し直してください。",
  "sstv.refuse.tiff": "これは TIFF ファイルです。SSTV で送れるのは JPEG・PNG・WebP・BMP・GIF です — いずれかの形式で書き出すか保存し直してください。",
  "sstv.refuse.raw": "これはカメラの RAW ファイルです。SSTV で送れるのは JPEG・PNG・WebP・BMP・GIF です — 先に JPEG に書き出してください。",
  "sstv.refuse.psd": "これは Photoshop ファイルです。SSTV で送れるのは JPEG・PNG・WebP・BMP・GIF です — いずれかの形式で書き出すか保存し直してください。",
  "sstv.refuse.svg": "これは SVG の図形データで、写真ではありません。SSTV で送れるのは JPEG・PNG・WebP・BMP・GIF です — いずれかの形式で書き出してください。",
  "sstv.rx.where": " このバンドの画像は {{freq}} {{mode}} に現れます。",
  "sstv.rx.off": "受信は停止中です — 何もデコードされていません。開始するにはアームを押してください。{{where}}",
  "sstv.rx.nocapture": "待ち受け中ですが、デコーダーに音声が全く届いていません — キャプチャデバイスから何も来ていません。入力デバイス（RX）が無線機になっているか確認してください。スピーカーで信号が聞こえていても、アプリが取り込めているとは限りません。",
  "sstv.rx.starting": "受信を開始しました — まだデコーダーに音声が届いていません。{{where}}",
  "sstv.rx.unsupported": "{{age}} 前に、このビルドではデコードできないモードの SSTV ヘッダーを受信しました{{vis}}。信号とオーディオ経路は正常です — Scottie・Martin・Robot・PD の画像はすべてデコードできます。",
  "sstv.rx.decoded": "アーム後 {{count}} 枚の画像をデコードしました。最後は {{age}} 前です。次のヘッダーを待ち受けています。",
  "sstv.rx.silent": "音声は届いていますが無音です。スピーカーで信号が聞こえる場合、アプリは別の入力を使っています — 入力デバイス（RX）を確認し、レベルが低いだけなら RX ゲインも確認してください。{{where}}",
  "sstv.rx.listening": "音声は入っていますが SSTV ヘッダーはまだです — 送信が始まると画像は自動的にデコードされます。{{where}}",
  "sstv.rx.unreachable": "受信状態を読み取れません — アプリが応答していません。デコーダーはまだ動作しているかもしれません。",
  "sstv.rx.openAudio": "オーディオ設定を開く",
